        Path baseDirPath = Paths.get(baseDir);

        if (!parentDir.startsWith(baseDirPath.toAbsolutePath())) {
            throw new IllegalArgumentException("Invalid file path: " + filename);
        }

        File file = new File(filePath.toString()); // Construct the file object using the safe path.
